        model3DPath: "/images/brands/mercedes/C-Class/W202/w2021.glb", model3DScale: 0.01, model3DRotation: [0, 0, 0], manualLightPositions: { headlights: { x: 0.16, y: -0.01, z: 0.6 } }, lightSettings: { headlightAngle: 0.25, headlightIntensity: 100, headlightOpacity: 0.5, headlightRadiusTop: 0.02, headlightTargetDistance: 4.5, headlightPenumbra: 0.1, meshGlowHeadlight: 28, meshGlowTaillight: 16, meshGlowDrl: 15, useBloom: true }, hotspotSettings: { distanceFactor: 1 },
