      rotatingAssembly: { pistonConstruction: "Cast aluminum alloy featuring oil cooling channels.", wristPinDiameter: "22 mm.", connectingRodLength: "144 mm.", crankMainJournal: "64.0 mm.", rodRatio: "1.67" },
